  /// Verifies a digital signature against a data string using the public key.
  static Future<bool> verify(String data, String signature, String publicKey) async {
    try {
      return await RSA.verifyPSS(
        signature,
        data,
        Hash.SHA256,
        SaltLength.AUTO,
        publicKey,
      );
    } catch (e) {
      return false;
    }
  }

  /// Simple SHA-256 hashing utility for internal data protection (like last_run_date).
  static String hashData(String data, String salt) {
    final bytes = utf8.encode(data + salt);
    return crypto.sha256.convert(bytes).toString();
  }
